#include "resident/kernel/catalog_section_observation.hpp"
// 只在精确亡者来源之后签发；先验原公职、具名军籍与同舟绑定，再核三种政治记录的双向覆盖。
#include "political_field_appointments_detail.hpp"
#include <set>
#include <limits>
namespace hanmo::resident::political_field_detail {
bool identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool same_source(const MilitaryFieldCommandSource& a,const MilitaryFieldCommandSource& b){return a.kind==b.kind&&a.id==b.id;}
bool same_observation(const MilitaryFieldCommandTarget& t,const MilitaryFieldCommandObservation& v){return v.kind==t.kind&&v.army_active&&v.organization_id==t.organization_id&&v.army_id==t.army_id&&v.campaign_id==t.campaign_id&&v.formation_source_id==t.formation_source_id&&v.unit_id==t.unit_id&&v.commander_actor_id==t.previous_actor_id&&same_source(v.command_source,t.previous_source)&&v.fleet_id==t.fleet_id&&v.commander_death&&v.commander_death->actor_id==t.predecessor_death.actor_id&&v.commander_death->casualty_fact_id==t.predecessor_death.casualty_fact_id&&v.commander_death->battle_id==t.predecessor_death.battle_id&&v.commander_death->tick==t.predecessor_death.tick;}
bool grant_covers(const Grant& g,const PoliticalFieldAppointmentPolicy& p,MilitaryFieldCommandKind kind,Integer tick){const auto* command=kind==MilitaryFieldCommandKind::unit?political_field_unit_grant:political_field_army_grant;return g.amount_limit>=1&&tick>=g.valid_from&&(!g.valid_until||tick<=*g.valid_until)&&g.wallet_ids.empty()&&g.inventory_ids.empty()&&std::find(g.allowed_command_kinds.begin(),g.allowed_command_kinds.end(),command)!=g.allowed_command_kinds.end()&&std::any_of(g.scopes.begin(),g.scopes.end(),[&](const auto& s){return s.kind==ScopeRef::Kind::site&&s.id==p.origin_site_id;});}
Outcome<StableId> current_authority(const PoliticalFieldAppointmentContext& c,const ActingAuthority& acting,const PoliticalFieldAppointmentPolicy& p,MilitaryFieldCommandKind kind){
    if(acting.organization_id!=p.organization_id)return {false,{},common_failure("PoliticalFieldOrganizationMismatch").error};const auto* command=kind==MilitaryFieldCommandKind::unit?political_field_unit_grant:political_field_army_grant;auto proof=check_authority(c.common,c.organizations,c.organization_catalog,acting,command,{ScopeRef::Kind::site,p.origin_site_id},1);if(!proof.ok)return {false,{},proof.error};const auto* office=c.organizations.offices.find(acting.office_id);if(office)for(const auto& id:office->grant_ids){const auto* g=c.organization_catalog.grants.find(id);if(g&&g->office_id==office->id&&grant_covers(*g,p,kind,c.common.tick()))return {true,id,{}};}return {false,{},common_failure("PoliticalFieldSpecificGrantRequired").error};
}
Status historical_authority(const PoliticalFieldAppointmentContext& c,const ActingAuthority& acting,const StableId& grant,const PoliticalFieldAppointmentPolicy& p,MilitaryFieldCommandKind kind,Integer tick,Integer seq){const auto* office=c.organization_catalog.offices.find(acting.office_id);const auto* g=c.organization_catalog.grants.find(grant);if(!office||office->organization_id!=p.organization_id||acting.organization_id!=p.organization_id||!g||g->office_id!=office->id||std::find(office->grant_ids.begin(),office->grant_ids.end(),grant)==office->grant_ids.end()||!grant_covers(*g,p,kind,tick))return common_failure("PoliticalFieldGrantHistoryMismatch",grant);return validate_historical_office_signer(c.common,c.organizations,c.organization_catalog,acting,tick,seq);}
// 整军接替再读候选人原部队当前来源；不能把尚未发生的第一步签受当作已任军官。
Status source(const PoliticalFieldAppointmentContext& c,const MilitaryFieldCommandTarget& t,Integer tick,const StableId& before){
    if(!c.military.current||!c.military.before_fact)return common_failure("PoliticalFieldMilitarySourceRequired");if(t.kind!=MilitaryFieldCommandKind::unit&&t.kind!=MilitaryFieldCommandKind::army)return common_failure("PoliticalFieldTargetMismatch");if(t.candidate_unit_source.has_value()!=(t.kind==MilitaryFieldCommandKind::army)||t.previous_actor_id==t.next_actor_id||t.predecessor_death.actor_id!=t.previous_actor_id||t.predecessor_death.tick<0||t.predecessor_death.tick>tick||t.previous_source.id.empty()||t.unit_id.empty()||!c.common.actor(t.next_actor_id))return common_failure("PoliticalFieldTargetMismatch");
    auto observed=before.empty()?c.military.current(t):c.military.before_fact(t,tick,before);if(!observed.ok)return {false,{},observed.error};if(!identity(observed.value.source_identity,c.common.state().identity)||!same_observation(t,observed.value))return common_failure("PoliticalFieldCommandSourceChanged",t.unit_id);
    if(t.kind==MilitaryFieldCommandKind::army){auto unit=t;unit.kind=MilitaryFieldCommandKind::unit;auto candidate=before.empty()?c.military.current(unit):c.military.before_fact(unit,tick,before);if(!candidate.ok)return {false,{},candidate.error};const auto& v=candidate.value;if(!identity(v.source_identity,c.common.state().identity)||!v.army_active||v.army_id!=t.army_id||v.organization_id!=t.organization_id||v.unit_id!=t.unit_id||v.commander_actor_id!=t.next_actor_id||v.fleet_id!=t.fleet_id||!same_source(v.command_source,*t.candidate_unit_source))return common_failure("PoliticalFieldCandidateNotCaptain",t.unit_id);}
    return common_success();
}
// 历史接触只取同军/同binding证明，不从今天的人物位置还原过去场所。
Status contact(const PoliticalFieldAppointmentContext& c,const MilitaryFieldCommandTarget& t,const StableId& actor,Integer tick,const StableId& before){if(!c.military.contact||!c.military.contact_before_fact)return common_failure("PoliticalFieldContactReadRequired");auto proof=before.empty()?c.military.contact(t,actor):c.military.contact_before_fact(t,actor,tick,before);if(!proof.ok)return {false,{},proof.error};const auto& v=proof.value;auto observed=before.empty()?c.military.current(t):c.military.before_fact(t,tick,before);if(!observed.ok)return {false,{},observed.error};if(v.observed_tick!=tick||v.boundary_fact_id!=before||(before.empty()?(!v.army_anchor||!v.actor_location):(v.army_anchor.has_value()||v.actor_location.has_value()))||v.vessel_id!=observed.value.vessel_id)return common_failure("PoliticalFieldContactBoundaryMismatch",actor);if(!identity(v.source_identity,c.common.state().identity)||!v.existing_army_member||v.army_id!=t.army_id||v.accepting_actor_id!=actor||v.previous_actor_id!=t.previous_actor_id||v.fleet_id!=t.fleet_id||(actor==t.next_actor_id&&v.unit_id!=t.unit_id)||(!t.fleet_id.empty()&&v.vessel_id.empty()))return common_failure("PoliticalFieldContactMismatch",actor);return common_success();}
Outcome<Audit> audit(const PoliticalFieldAppointmentContext& c){
    const auto fail=[](const StableId& code,const StableId& id=StableId{})->Outcome<Audit>{return {false,{},common_failure(code,id).error};};if(c.state.version!=1)return fail("UnsupportedPoliticalFieldVersion");auto directory=validate_political_field_catalog(c.common_catalog,c.organization_catalog,c.catalog,c.military);if(!directory.ok)return {false,{},directory.error};Audit out;std::set<StableId> seen;Integer prior=0,tick=-1;
    for(const auto& id:c.common.state().facts.order()){
        const auto* h=c.common.state().facts.find(id);if(!h||h->id!=id)return fail("PoliticalFieldFactOrderMismatch",id);const bool issue=h->kind==political_field_issue_kind,answer=h->kind==political_field_accept_kind||h->kind==political_field_decline_kind,withdraw=h->kind==political_field_withdraw_kind;if(!issue&&!answer&&!withdraw){seen.insert(id);continue;}if(!c.catalog.enabled||h->domain!="politics")return fail("PoliticalFieldProfileRequired",id);
        auto seq=organization_instance_sequence(id,issue?"political_field_authorization":answer?"political_field_answer":"political_field_withdrawal");if(!seq||*seq<=prior||*seq>=c.common.state().next_instance_id)return fail("PoliticalFieldFactOrderMismatch",id);Integer at=0;
        if(issue){
            const auto* v=c.state.authorizations.find(id);if(!v||v->id!=id||c.state.answers.find(id)||c.state.withdrawals.find(id))return fail("PoliticalFieldAuthorizationMissing",id);const auto* p=c.catalog.policies.find(v->policy_id);const auto* person=c.common.state().actors.find(v->target.next_actor_id);const auto* death=c.common.state().facts.find(v->target.predecessor_death.casualty_fact_id);
            if(!p||!person||!person->birth_tick||v->tick<0||v->tick>c.common.tick()||*person->birth_tick>v->tick-18*720||v->target.organization_id!=p->organization_id||(v->target.kind==MilitaryFieldCommandKind::unit?!p->allow_unit:!p->allow_army)||v->tick>std::numeric_limits<Integer>::max()-p->response_ticks||v->answer_before_tick!=v->tick+p->response_ticks||!death||death->domain!="military"||death->kind!="military_casualties"||!seen.count(death->id))return fail("PoliticalFieldAuthorizationMismatch",id);
            auto valid=historical_authority(c,v->authority,v->grant_id,*p,v->target.kind,v->tick,*seq);if(!valid.ok)return {false,{},valid.error};valid=source(c,v->target,v->tick,id);if(!valid.ok)return {false,{},valid.error};auto obs=c.military.before_fact(v->target,v->tick,id);if(!obs.ok)return {false,{},obs.error};if(obs.value.origin_garrison_id!=p->origin_garrison_id)return fail("PoliticalFieldOriginMismatch",id);for(const auto& actor:{v->authority.actor_id,v->target.next_actor_id}){valid=contact(c,v->target,actor,v->tick,id);if(!valid.ok)return {false,{},valid.error};}
            for(const auto& row:out.authorizations){const auto& old=*row.second;if(old.target.kind!=v->target.kind||old.target.army_id!=v->target.army_id||(v->target.kind==MilitaryFieldCommandKind::unit&&old.target.unit_id!=v->target.unit_id))continue;if(out.withdrawals.count(old.id))continue;const auto answered=out.answers.find(old.id);if(answered!=out.answers.end()&&!answered->second->accepted)continue;auto deadline=answered==out.answers.end()?old.answer_before_tick:answered->second->apply_before_tick;if(v->tick>=deadline)continue;auto a=historical_authority(c,old.authority,old.grant_id,*c.catalog.policies.find(old.policy_id),old.target.kind,v->tick,*seq);auto s=source(c,old.target,v->tick,id);if(a.ok&&s.ok)return fail("PoliticalFieldDuplicatePending",id);}
            out.authorizations.emplace(id,v);at=v->tick;
        }else if(answer){
            const auto* v=c.state.answers.find(id);if(!v||v->id!=id||c.state.authorizations.find(id)||c.state.withdrawals.find(id))return fail("PoliticalFieldAnswerMissing",id);auto old=out.authorizations.find(v->authorization_fact_id);if(old==out.authorizations.end()||out.answers.count(v->authorization_fact_id)||out.withdrawals.count(v->authorization_fact_id))return fail("PoliticalFieldAnswerSourceMismatch",id);const auto& a=*old->second;const auto* p=c.catalog.policies.find(a.policy_id);if(v->actor_id!=a.target.next_actor_id||v->accepted!=(h->kind==political_field_accept_kind)||v->tick<a.tick||v->tick>=a.answer_before_tick||v->tick>std::numeric_limits<Integer>::max()-p->arrival_ticks||v->apply_before_tick!=(v->accepted?v->tick+p->arrival_ticks:0)||v->witness_actor_ids.empty()||v->witness_actor_ids.front()!=v->actor_id||v->witness_actor_ids.size()>2||(v->witness_actor_ids.size()==2&&(v->witness_actor_ids.back()!=a.authority.actor_id||v->actor_id==a.authority.actor_id)))return fail("PoliticalFieldAnswerMismatch",id);
            if(v->accepted){auto valid=historical_authority(c,a.authority,a.grant_id,*p,a.target.kind,v->tick,*seq);if(!valid.ok)return {false,{},valid.error};valid=source(c,a.target,v->tick,id);if(!valid.ok)return {false,{},valid.error};valid=contact(c,a.target,v->actor_id,v->tick,id);if(!valid.ok)return {false,{},valid.error};}if(v->witness_actor_ids.size()==2)for(const auto& actor:v->witness_actor_ids){auto valid=contact(c,a.target,actor,v->tick,id);if(!valid.ok)return {false,{},valid.error};}out.answers.emplace(a.id,v);at=v->tick;
        }else{
            const auto* v=c.state.withdrawals.find(id);if(!v||v->id!=id||c.state.authorizations.find(id)||c.state.answers.find(id))return fail("PoliticalFieldWithdrawalMissing",id);auto old=out.authorizations.find(v->authorization_fact_id);if(old==out.authorizations.end()||out.withdrawals.count(v->authorization_fact_id))return fail("PoliticalFieldWithdrawalSourceMismatch",id);const auto& a=*old->second;auto answer_it=out.answers.find(a.id);if(v->authority.actor_id!=a.authority.actor_id||v->authority.office_id!=a.authority.office_id||v->tick<a.tick||(answer_it!=out.answers.end()&&!answer_it->second->accepted)||v->witness_actor_ids.empty()||v->witness_actor_ids.front()!=v->authority.actor_id||v->witness_actor_ids.size()>2||(v->witness_actor_ids.size()==2&&(v->witness_actor_ids.back()!=a.target.next_actor_id||v->authority.actor_id==a.target.next_actor_id)))return fail("PoliticalFieldWithdrawalMismatch",id);auto valid=historical_authority(c,v->authority,v->grant_id,*c.catalog.policies.find(a.policy_id),a.target.kind,v->tick,*seq);if(!valid.ok)return {false,{},valid.error};valid=source(c,a.target,v->tick,id);if(!valid.ok)return {false,{},valid.error};if(v->witness_actor_ids.size()==2)for(const auto& actor:v->witness_actor_ids){valid=contact(c,a.target,actor,v->tick,id);if(!valid.ok)return {false,{},valid.error};}out.withdrawals.emplace(a.id,v);at=v->tick;
        }
        if(at<tick||at>c.common.tick())return fail("PoliticalFieldFactOrderMismatch",id);prior=*seq;tick=at;seen.insert(id);
    }
    if(out.authorizations.size()!=c.state.authorizations.size()||out.answers.size()!=c.state.answers.size()||out.withdrawals.size()!=c.state.withdrawals.size())return fail("PoliticalFieldOrphanPayload");for(const auto& r:c.state.authorizations.rows())if(r.first!=r.second.id)return fail("PoliticalFieldOrphanPayload",r.first);for(const auto& r:c.state.answers.rows())if(r.first!=r.second.id)return fail("PoliticalFieldOrphanPayload",r.first);for(const auto& r:c.state.withdrawals.rows())if(r.first!=r.second.id)return fail("PoliticalFieldOrphanPayload",r.first);return {true,std::move(out),{}};
}
}
namespace hanmo::resident {
Status validate_political_field_catalog(const CommonCatalog& common,const OrganizationCatalog& organizations,const PoliticalFieldAppointmentCatalog& catalog,const PoliticalFieldMilitaryRead& military){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 96, "PoliticalFieldAppointmentCatalog", "validate_political_field_catalog", &catalog);
if(catalog.version!=1)return common_failure("UnsupportedPoliticalFieldVersion");if(!catalog.enabled)return catalog.policies.empty()?common_success():common_failure("UnexpectedPoliticalFieldCatalog");if(!organizations.enabled||!military.garrison_site||catalog.policies.empty())return common_failure("PoliticalFieldDependenciesRequired");for(const auto& r:catalog.policies.rows()){const auto& p=r.second;if(r.first!=p.id||!organizations.organizations.find(p.organization_id)||!common.places.find(p.origin_site_id)||military.garrison_site(p.origin_garrison_id)!=std::optional<StableId>{p.origin_site_id}||p.response_ticks<=0||p.arrival_ticks<=0||(!p.allow_unit&&!p.allow_army))return common_failure("PoliticalFieldPolicyMismatch",r.first);}return common_success();}
Status validate_political_field_appointments(const PoliticalFieldAppointmentContext& c){auto valid=political_field_detail::audit(c);return valid.ok?common_success():Status{false,{},valid.error};}
}
